package testng_extra;

import org.testng.Reporter;
import org.testng.annotations.Test;

public class DemoTest1 {

	// Reporter class is used for test methods to log messages
	//		that will included in the HTML reports generated by TestNG
	
	@Test
	public void case1() {
		System.out.println("hello...");      // console
	}
	
	@Test
	public void case2() {
		Reporter.log("case 2 : report log");    // report
	}
	
	@Test
	public void case3() {
		Reporter.log("case 3 : report + console log", true);    // report
	}
}
